import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { fetchVideoMetadata, downloadAndUploadVideo } from "../axios-use/api";
import "./clipper.css";

function Clipper() {
    const [videoURL, setVideoURL] = useState("");
    const [videoData, setVideoData] = useState(null);
    const [loading, setLoading] = useState(false);
    const [processing, setProcessing] = useState(false);
    const [error, setError] = useState(null);
    const [optimizationType, setOptimizationType] = useState("");
    const [aspectRatio, setAspectRatio] = useState("16:9");
    const [clipLength, setClipLength] = useState("90s");
    const [clipCount, setClipCount] = useState(1);
    const [selectedFeatures, setSelectedFeatures] = useState([]);
    const navigate = useNavigate();

    const handleFetch = async () => {
        setLoading(true);
        setError(null);
        setVideoData(null);

        if (!videoURL.trim()) {
            setError("Please enter a valid YouTube URL.");
            setLoading(false);
            return;
        }

        try {
            const data = await fetchVideoMetadata(videoURL);
            setVideoData(data);
            const downloadResponse = await downloadAndUploadVideo(videoURL);
            console.log("Video download and upload response:", downloadResponse);
        } catch (err) {
            setError(err.response?.data?.error || "Error fetching video. Please try again.");
            console.error("Error during fetch:", err);
        } finally {
            setLoading(false);
        }
    };

    const handleOptimizationTypeChange = (type) => {
        setOptimizationType(type);
        setAspectRatio(type === "Long Form" ? "16:9" : "9:16");
    };

    const handleFeatureToggle = (feature) => {
        setSelectedFeatures((prevFeatures) =>
            prevFeatures.includes(feature)
                ? prevFeatures.filter((f) => f !== feature) // Remove feature if already selected
                : [...prevFeatures, feature] // Add feature if not selected
        );
    };

    const handleGenerateClick = async () => {
        if (!videoData) {
            alert("Please fetch video data before generating.");
            return;
        }

        const payload = {
            videoURL,
            optimizationType,
            aspectRatio,
            clipLength,
            clipCount,
            features: selectedFeatures, // Include selected features in the payload
        };

        setProcessing(true);

        try {
            console.log("Payload:", payload);
            const csrfToken = document.cookie
                .split("; ")
                .find((row) => row.startsWith("csrftoken"))
                ?.split("=")[1];

            const response = await axios.post(
                "http://127.0.0.1:8000/api/process_short_form_video/",
                payload,
                {
                    headers: {
                        "X-CSRFToken": csrfToken,
                        "Content-Type": "application/json",
                    },
                }
            );

            alert(response.data.message || "Video generation started!");

            navigate("/clippreview", {
                state: {
                    clipPaths: response.data.clips,
                    videoURL,
                },
            });
        } catch (err) {
            console.error("Error generating video:", err);
            alert(err.response?.data?.error || "Error during video generation. Please try again.");
        } finally {
            setProcessing(false);
        }
    };

    return (
        <div className="clipper-container">
            <h1>YouTube Video Clipper</h1>

            <div className="url-input-container">
                <input
                    type="text"
                    placeholder="Enter YouTube URL"
                    value={videoURL}
                    onChange={(e) => setVideoURL(e.target.value)}
                    className="url-input"
                />
                <button onClick={handleFetch} disabled={loading} className="fetch-btn">
                    {loading ? "Fetching..." : "Fetch Video"}
                </button>
            </div>

            {error && <p className="error-message">{error}</p>}

            {videoData && (
                <div className="video-preview-container">
                    <h2>{videoData.title}</h2>
                    <img
                        src={videoData.thumbnail}
                        alt="Video Thumbnail"
                        className="video-thumbnail"
                    />
                </div>
            )}

            <div className="optimization-type">
                <h3>Choose Optimization Type:</h3>
                <button
                    className={optimizationType === "Long Form" ? "active" : ""}
                    onClick={() => handleOptimizationTypeChange("Long Form")}
                >
                    Long Form
                </button>
                <button
                    className={optimizationType === "Short Form" ? "active" : ""}
                    onClick={() => handleOptimizationTypeChange("Short Form")}
                >
                    Short Form
                </button>
            </div>

            {optimizationType && (
                <div className="settings-container">
                    <h4>Choose Features:</h4>
                    <div className="features">
                        {["Noise Reduction", "Video Quality", "SEO", "Captions"].map((feature) => (
                            <button
                                key={feature}
                                className={selectedFeatures.includes(feature) ? "feature-btn active" : "feature-btn"}
                                onClick={() => handleFeatureToggle(feature)}
                            >
                                {feature}
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {processing && <p className="processing-message">Processing your video. Please wait...</p>}

            <div className="generate-btn">
                <button
                    onClick={handleGenerateClick}
                    disabled={!optimizationType || !videoData || processing}
                >
                    {processing ? "Processing..." : "Generate"}
                </button>
            </div>
        </div>
    );
}

export default Clipper;
